@Component("supplier-entity-projector")
public class SupplierEntityProjector implements EntityProjector<Supplier>{
		
	// core constructor
	public SupplierEntityProjector(ProjectorRegistry registry,
										SupplierRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Supplier> getEntityClass() {
		return Supplier.class;
	}

    /*
	 * Insert a Supplier
	 * 
     * @param	entity Supplier
     */
    public Supplier create( Supplier entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Supplier
	 * 
     * @param	entity Supplier
     */
    public Supplier update( Supplier entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Supplier
	 * 
     * @param	id		UUID
     */
    public Supplier delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Supplier entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Merchant
     * 
     * @param	parentId	UUID
     * @param	assignment 	Merchant 
     * @return	Supplier
     */
    public Supplier assignMerchant( UUID parentId, Merchant assignment ) {
	    LOGGER.info("assigning Merchant as " + assignment.toString() );

	    Supplier parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Merchant.class, assignment.getMerchantId());

	    // ------------------------------------------
		// assign the Merchant to the parent entity
		// ------------------------------------------ 
	    parentEntity.setMerchant( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Merchant
	 * 
	 * @param	parentId		UUID
	 * @return	Supplier
	 */
	public Supplier unAssignMerchant( UUID parentId ) {
		Supplier parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Merchant on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Merchant on the parent entithy
		// ------------------------------------------     
	    parentEntity.setMerchant(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Products
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Supplier
     */
    public Supplier addToProducts( UUID parentId, Product addTo ) {
	    LOGGER.info("handling AssignProductsToSupplierEvent - " );
	    
	    Supplier parentEntity = repository.findById(parentId).get();
	    Product child = registry.project( Product.class, addTo.getProductId());
	    
	    parentEntity.getProducts().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Products
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Supplier
     */
	public Supplier removeFromProducts( UUID parentId, Product removeFrom ) {
	    LOGGER.info("handling RemoveProductsFromSupplierEvent " );
	
	    Supplier parentEntity = repository.findById(parentId).get();
	    Product child = registry.project( Product.class, removeFrom.getProductId());
	    
	    parentEntity.getProducts().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the FulfillmentCenters
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Supplier
     */
    public Supplier addToFulfillmentCenters( UUID parentId, FulfillmentCenter addTo ) {
	    LOGGER.info("handling AssignFulfillmentCentersToSupplierEvent - " );
	    
	    Supplier parentEntity = repository.findById(parentId).get();
	    FulfillmentCenter child = registry.project( FulfillmentCenter.class, addTo.getFulfillmentCenterId());
	    
	    parentEntity.getFulfillmentCenters().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the FulfillmentCenters
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Supplier
     */
	public Supplier removeFromFulfillmentCenters( UUID parentId, FulfillmentCenter removeFrom ) {
	    LOGGER.info("handling RemoveFulfillmentCentersFromSupplierEvent " );
	
	    Supplier parentEntity = repository.findById(parentId).get();
	    FulfillmentCenter child = registry.project( FulfillmentCenter.class, removeFrom.getFulfillmentCenterId());
	    
	    parentEntity.getFulfillmentCenters().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Supplier via an FindSupplierQuery
     * @return 	query	FindSupplierQuery
     */
    @SuppressWarnings("unused")
    public Supplier find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Supplier - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Suppliers
     *
     * @param	query	FindAllSupplierQuery 
     * @return 	List<Supplier> 
     */
    @SuppressWarnings("unused")
    public List<Supplier> findAll( FindAllSupplierQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Supplier - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final SupplierRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(SupplierEntityProjector.class.getName());

}
